const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alabama = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Alabama'))
    .geometry();

  const date2003Start = '2003-01-01';
  const date2003End = '2003-12-31';
  const date2012Start = '2012-01-01';
  const date2012End = '2012-12-31';

  // 2. Data Acquisition & Check
  const grace = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND');

  const col2003 = grace.filterDate(date2003Start, date2003End)
    .filterBounds(alabama);

  const col2012 = grace.filterDate(date2012Start, date2012End)
    .filterBounds(alabama);

  const size2003 = col2003.size().getInfo();
  const size2012 = col2012.size().getInfo();

  console.log('2003 Images:', size2003);
  console.log('2012 Images:', size2012);

  if (size2003 === 0 || size2012 === 0) {
    console.log('No data available for one or both years.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate mean water storage
  const mean2003 = col2003.select('lwe_thickness_csr').mean();
  const mean2012 = col2012.select('lwe_thickness_csr').mean();

  // Check pixel counts
  const count2003 = mean2003.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alabama,
    scale: 25000,
    maxPixels: 1e9
  }).get('lwe_thickness_csr').getInfo();

  const count2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: alabama,
    scale: 25000,
    maxPixels: 1e9
  }).get('lwe_thickness_csr').getInfo();

  console.log('2003 Valid Pixels:', count2003);
  console.log('2012 Valid Pixels:', count2012);

  if (count2003 === 0 || count2012 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation
  const val2003 = mean2003.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: alabama,
    scale: 25000,
    maxPixels: 1e9
  }).get('lwe_thickness_csr').getInfo();

  const val2012 = mean2012.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: alabama,
    scale: 25000,
    maxPixels: 1e9
  }).get('lwe_thickness_csr').getInfo();

  console.log('2003 Mean Water Storage (cm):', val2003 !== null ? val2003.toFixed(2) : 'null');
  console.log('2012 Mean Water Storage (cm):', val2012 !== null ? val2012.toFixed(2) : 'null');

  // 5. Validation & Final Answer
  if (val2003 === null || val2012 === null || isNaN(val2003) || isNaN(val2012)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  const change = val2012 - val2003;
  console.log('Change (2012-2003):', change.toFixed(2), 'cm');

  if (val2012 < val2003) {
    console.log('Water storage decreased from 2003 to 2012.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water storage did not decrease from 2003 to 2012.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
